// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));

        address deployer = address(this);

        if (caller != deployer) {
            bool ok;
            try c.setOwner(caller) {
                ok = true;
            } catch {
                ok = false;
            }
            vm.assume(ok);
        }

        bool ok2;
        vm.prank(caller);
        try c.setOwner(newOwner) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        if (ok2) {
            assertTrue(c.owner() == newOwner);
        } else {
            assertTrue(false);
        }
    }
}
